service.method:

UPDATE UPSPS
    SET   NAME = ${NAME}
        , DESCRIPTION = ${DESCRIPTION}
        , DATA = ${DATA}
    WHERE 
        HOUSE_CODE = ${session.HOUSE_CODE}
    AND USER_ID = ${session.ID}
    AND CLASS = ${CLASS}
    AND CODE = ${CODE}


INSERT INTO UPSPS (
      HOUSE_CODE
    , USER_ID
    , CLASS
    , CODE
    , NAME
    , DESCRIPTION
    , DATA
    , USE_FLAG
) VALUES (
      ${session.HOUSE_CODE}
    , ${session.ID}
    , ${CLASS}
    , ${CODE}
    , ${NAME}
    , ${DESCRIPTION}
    , ${DATA}
    , 'N'
)


DELETE FROM UPSPS
WHERE 
    HOUSE_CODE = ${session.HOUSE_CODE}
AND USER_ID = ${session.ID}
AND CLASS = ${CLASS}
AND CODE = ${CODE}


UPDATE UPSPS
    SET USE_FLAG = 'N'
WHERE 
    HOUSE_CODE = ${session.HOUSE_CODE}
AND USER_ID = ${session.ID}
AND CLASS = ${CLASS}


UPDATE UPSPS
    SET USE_FLAG = ${USE_FLAG}
WHERE 
    HOUSE_CODE = ${session.HOUSE_CODE}
AND USER_ID = ${session.ID}
AND CLASS = ${CLASS}
AND CODE = ${CODE}
